use std::fmt::Write as _;
use std::io::{self, Read, Write};

/// One cart line: `item SKU QTY UNIT`.
struct CartLine {
    sku: String,
    qty: i128,
    unit: i128,
    base: i128,
    cur: i128,
}

/// A discount rule. The evaluation loop only sees this interface, so a new
/// kind can be added by implementing it.
trait Rule {
    fn kind(&self) -> &'static str;
    /// Applies the rule, returning its saving. `cart_discount` is the
    /// whole-cart discount accumulated so far (used by threshold rules).
    fn apply(&self, lines: &mut [CartLine], cart_discount: &mut i128) -> i128;
}

fn matches(target: &str, sku: &str) -> bool {
    target == "*" || target == sku
}

struct Percent {
    target: String,
    pct: i128,
}

impl Rule for Percent {
    fn kind(&self) -> &'static str {
        "percent"
    }
    fn apply(&self, lines: &mut [CartLine], _cart: &mut i128) -> i128 {
        let mut saving = 0;
        for l in lines.iter_mut().filter(|l| matches(&self.target, &l.sku)) {
            let d = l.cur * self.pct / 100;
            l.cur -= d;
            saving += d;
        }
        saving
    }
}

struct Fixed {
    target: String,
    cents: i128,
}

impl Rule for Fixed {
    fn kind(&self) -> &'static str {
        "fixed"
    }
    fn apply(&self, lines: &mut [CartLine], _cart: &mut i128) -> i128 {
        let mut saving = 0;
        for l in lines.iter_mut().filter(|l| matches(&self.target, &l.sku)) {
            let d = l.cur.min(self.cents);
            l.cur -= d;
            saving += d;
        }
        saving
    }
}

struct Bogo {
    target: String,
    buy: i128,
    get: i128,
}

impl Rule for Bogo {
    fn kind(&self) -> &'static str {
        "bogo"
    }
    fn apply(&self, lines: &mut [CartLine], _cart: &mut i128) -> i128 {
        let mut saving = 0;
        for l in lines.iter_mut().filter(|l| matches(&self.target, &l.sku)) {
            let free = (l.qty / (self.buy + self.get)) * self.get;
            let d = l.cur.min(free * l.unit);
            l.cur -= d;
            saving += d;
        }
        saving
    }
}

struct Threshold {
    threshold: i128,
    pct: i128,
}

impl Rule for Threshold {
    fn kind(&self) -> &'static str {
        "threshold"
    }
    fn apply(&self, lines: &mut [CartLine], cart: &mut i128) -> i128 {
        let sum: i128 = lines.iter().map(|l| l.cur).sum();
        let running = sum - *cart;
        if running >= self.threshold {
            let d = running * self.pct / 100;
            *cart += d;
            d
        } else {
            0
        }
    }
}

/// Parses an unsigned number of at most 9 digits.
fn num(s: &str) -> Option<i128> {
    if s.is_empty() || s.len() > 9 || !s.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    s.parse().ok()
}

enum Entry {
    Item(CartLine),
    Rule(Box<dyn Rule>),
}

fn parse_item(f: &[&str]) -> Option<Entry> {
    if f.len() != 4 {
        return None;
    }
    let qty = num(f[2])?;
    let unit = num(f[3])?;
    if qty < 1 {
        return None;
    }
    let base = qty * unit;
    Some(Entry::Item(CartLine {
        sku: f[1].to_string(),
        qty,
        unit,
        base,
        cur: base,
    }))
}

fn parse_rule(f: &[&str]) -> Option<Entry> {
    if f.len() < 2 {
        return None;
    }
    let rule: Box<dyn Rule> = match f[1] {
        "percent" if f.len() == 4 => {
            let pct = num(f[3])?;
            if pct > 100 {
                return None;
            }
            Box::new(Percent {
                target: f[2].to_string(),
                pct,
            })
        }
        "fixed" if f.len() == 4 => Box::new(Fixed {
            target: f[2].to_string(),
            cents: num(f[3])?,
        }),
        "bogo" if f.len() == 5 => {
            let buy = num(f[3])?;
            let get = num(f[4])?;
            if buy < 1 || get < 1 {
                return None;
            }
            Box::new(Bogo {
                target: f[2].to_string(),
                buy,
                get,
            })
        }
        "threshold" if f.len() == 4 => {
            let threshold = num(f[2])?;
            let pct = num(f[3])?;
            if pct > 100 {
                return None;
            }
            Box::new(Threshold { threshold, pct })
        }
        _ => return None,
    };
    Some(Entry::Rule(rule))
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut errors = String::new();
    let mut lines: Vec<CartLine> = Vec::new();
    let mut rules: Vec<Box<dyn Rule>> = Vec::new();
    let mut error_count = 0;

    for (idx, raw) in input.lines().enumerate() {
        if raw.is_empty() {
            continue;
        }
        let f: Vec<&str> = raw.split(' ').collect();
        let entry = match f[0] {
            "item" => parse_item(&f),
            "rule" => parse_rule(&f),
            _ => None,
        };
        match entry {
            Some(Entry::Item(line)) => lines.push(line),
            Some(Entry::Rule(rule)) => rules.push(rule),
            None => {
                error_count += 1;
                let _ = writeln!(errors, "error line {}: {}", idx + 1, raw);
            }
        }
    }

    let mut cart_discount: i128 = 0;
    let mut rule_out = String::new();
    for (i, rule) in rules.iter().enumerate() {
        let saving = rule.apply(&mut lines, &mut cart_discount);
        let _ = writeln!(rule_out, "rule {} {} {}", i + 1, rule.kind(), saving);
    }

    let mut out = errors;
    for l in &lines {
        let _ = writeln!(out, "item {} {} {}", l.sku, l.base, l.cur);
    }
    out.push_str(&rule_out);

    let sum: i128 = lines.iter().map(|l| l.cur).sum();
    let total = (sum - cart_discount).max(0);
    let _ = writeln!(out, "total {}", total);

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    handle.write_all(out.as_bytes()).unwrap();
    handle.flush().unwrap();
    if error_count > 0 {
        std::process::exit(1);
    }
}
